import{_ as u,a0 as i,w as o,s as p,ao as l,I as r,x as a,a1 as n,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"在Ubuntu 14.04 中修復無法清空回收站的問題 | LCTT x X-CMD","titleTemplate":false,"description":"在Ubuntu 14.04 中修復無法清空回收站的問題 | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在Ubuntu 14.04 中修復無法清空回收站的問題 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在Ubuntu 14.04 中修復無法清空回收站的問題 | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150209 Fix Cannot Empty Trash In Ubuntu 14.04 [Quick Tip]","title":"在Ubuntu 14.04 中修復無法清空回收站的問題","tag":"201504","desc":""},"relativePath":"201504/20150209 Fix Cannot Empty Trash In Ubuntu 14.04 [Quick Tip].md","filePath":"[post].md"}'),d={name:"201504/20150209 Fix Cannot Empty Trash In Ubuntu 14.04 [Quick Tip].md"};function m(f,t,T,b,h,x){const e=i("Link");return o(),p("div",null,[t[13]||(t[13]=l(`<h1 id="在ubuntu-14-04-中修復無法清空回收站的問題" tabindex="-1">在Ubuntu 14.04 中修復無法清空回收站的問題 <a class="header-anchor" href="#在ubuntu-14-04-中修復無法清空回收站的問題" aria-label="Permalink to “在Ubuntu 14.04 中修復無法清空回收站的問題”">​</a></h1><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/02/empty-the-trash.jpg" alt=""></p><h3 id="問題" tabindex="-1">問題 <a class="header-anchor" href="#問題" aria-label="Permalink to “問題”">​</a></h3><p><strong>我遇到了無法在Ubuntu 14.04中清空回收站的問題</strong>。我右鍵回收站圖標並選擇清空回收站，就像我一直做的那樣。我看到進度條顯示刪除文件中過了一段時間。但是它停止了，並且Nautilus文件管理也停止了。我不得不在終端中停止了它。</p><p>但是這很痛苦因為文件還在垃圾箱中。並且我反覆嘗試清空後窗口都凍結了。</p><h3 id="方案" tabindex="-1">方案 <a class="header-anchor" href="#方案" aria-label="Permalink to “方案”">​</a></h3><p>老實説，我不知道什麼導致了這個問題。但是我有一個解決方案如果你在Ubuntu 14.04或者14.10遇到這個問題的話。</p><p>打開終端並使用下面的命令:</p><pre><code>sudo rm -rf ~/.local/share/Trash/*
</code></pre><p>這裏注意你的輸入。你使用超級管理員權限來運行刪除命令。我相信你不會刪除其他文件或者目錄。</p><p>上面的命令會刪除回收站目錄下的所有文件。換句話説，這是用命令清空垃圾箱。使用完上面的命令後，你會看到垃圾箱已經清空了。如果你清空了所有文件，你不應該在看到Nautilus崩潰的問題了。</p><h3 id="對你有用麼" tabindex="-1">對你有用麼？ <a class="header-anchor" href="#對你有用麼" aria-label="Permalink to “對你有用麼？”">​</a></h3><p>我希望這篇貼士對你有用，今後你也不會在Ubuntu或者其他發行版中再遇到相同的問題。如果你遇到任何問題請讓我知道。</p><hr>`,14)),r("p",null,[t[1]||(t[1]=a("via: ",-1)),n(e,{href:"http://itsfoss.com/fix-empty-trash-ubuntu/"},{default:s(()=>[...t[0]||(t[0]=[a("http://itsfoss.com/fix-empty-trash-ubuntu/",-1)])]),_:1})]),r("p",null,[t[5]||(t[5]=a("作者：",-1)),n(e,{href:"http://itsfoss.com/author/abhishek/"},{default:s(()=>[...t[2]||(t[2]=[a("Abhishek",-1)])]),_:1}),t[6]||(t[6]=a(" 譯者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:s(()=>[...t[3]||(t[3]=[a("geekpi",-1)])]),_:1}),t[7]||(t[7]=a(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:s(()=>[...t[4]||(t[4]=[a("wxy",-1)])]),_:1})]),r("p",null,[t[10]||(t[10]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[8]||(t[8]=[a("LCTT",-1)])]),_:1}),t[11]||(t[11]=a(" 原創翻譯，",-1)),n(e,{href:"http://linux.cn/"},{default:s(()=>[...t[9]||(t[9]=[a("Linux中國",-1)])]),_:1}),t[12]||(t[12]=a(" 榮譽推出",-1))])])}const g=u(d,[["render",m]]);export{_ as __pageData,g as default};
